def workitems(start) -> bool:
    cnt = 1
    while True:
        if start:
            print("Begin Invocation ", cnt)
            # m5.stats.reset()
        else:
            print("End Invocation ", cnt)
            # m5.stats.dump()
            cnt += 1

        if args.mode == "evaluation" and cnt >= args.num_invocations:
            yield True
        yield False


def executeExit() -> bool:
    global exits
    if args.mode == "setup":
        print("1: BOOTING complete")
        yield False

        print("2: Stop setup simulation")
        yield True
    else:
        for i in range(9):
            m5.stats.dump()
            # Generate a unique filename for each dump
            new_filename = f"stats_dump_{i}.txt"
            
            # Rename the stats.txt file
            if os.path.exists("stats.txt"):  # Ensure the file exists before renaming
                os.rename("stats.txt", new_filename)
            else:
                print("Stats file not found. Ensure stats.dump() is generating stats.")
            m5.stats.reset()
            print("Continue simulation")
            yield False
        print("Simulation done")
        m5.stats.dump()
        yield True


def executeFail() -> bool:
    #print("1: Client started")
    #yield False
    #print("1: Function warming starts")
    #yield False
    print("A: Creating checkpoint")
    # processor.switch()
    if args.mode == "setup":
        m5.checkpoint(f"{args.checkpoint_dir}/{args.function}")

    yield False

    while True:
        print("1: Function warming done")
        yield False


# Here we set a full system workload.
board.set_kernel_disk_workload(
    kernel=KernelResource(args.kernel),
    disk_image=DiskImageResource(args.disk),
    readfile_contents=writeRunScript(args.function),
    kernel_args=[
        "earlyprintk=ttyS0",
        "console=ttyS0",
        "lpj=7999923",
        "root=/dev/hda2",
        "isolcpus=1",
        "cloud-init=disabled",
    ],
    checkpoint=Path(f"{args.checkpoint_dir}/{args.function}")
    if args.mode == "evaluation"
    else None,
)
# We define the system with the aforementioned system defined.
simulator = Simulator(
    board=board,
    on_exit_event={
        # ExitEvent.EXIT: (func() for func in [processor.switch]),
        ExitEvent.WORKBEGIN: workitems(True),
        ExitEvent.WORKEND: workitems(False),
        ExitEvent.EXIT: executeExit(),
        ExitEvent.FAIL: executeFail(),
    },
)

# Once the system successfully boots, it encounters an
# `m5_exit instruction encountered`. We stop the simulation then. When the
# simulation has ended you may inspect `m5out/board.terminal` to see
# the stdout.
simulator.run()
